  "check_code": "import hashlib
import json
import re
import sqlite3
from pathlib import Path


SYSTEM_NAME = "microsoft_project_implementation"
TARGET_TASK_ID = "IMP-24-088"
EXPECTED_EVIDENCE = "Approved October rota extract"
BASELINE_TASK_COUNT = 32
BASELINE_UPDATE_COUNT = 80
UNRELATED_TASKS_DIGEST = "3371ce381863c218ec2b5e047b079931514ccd49dece660971ecde9b508f1ff1"
BASELINE_UPDATES_DIGEST = "6a65c5c705cccc59a7f6098f4ee18894a044fc4369aa691b043397fd3efa9c10"


def _db_path(ws):
    return Path(ws).resolve().parent / "system" / SYSTEM_NAME / "state.db"


def _baseline_path(ws):
    return _db_path(ws).with_name("state.db.pinned_backup")


def _connect(path):
    connection = sqlite3.connect(path)
    connection.row_factory = sqlite3.Row
    return connection


def _norm_label(value):
    return " ".join(re.findall(r"[a-z0-9]+", str(value or "").lower()))


def _row_dict(row):
    return dict(row) if row is not None else None


def _rows_by_key(connection, table, key_column, where="", params=()):
    query = f"SELECT * FROM {table}"
    if where:
        query += f" WHERE {where}"
    return {
        row[key_column]: dict(row)
        for row in connection.execute(query, params).fetchall()
    }


def _logical_digest(rows):
    payload = json.dumps(
        rows,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    )
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def check_target_evidence_verified(ws):
    connection = _connect(_db_path(ws))
    try:
        row = connection.execute(
            "SELECT task_id, status, evidence_status FROM implementation_tasks WHERE task_id = ?",
            (TARGET_TASK_ID,),
        ).fetchone()
    finally:
        connection.close()
    if row is None:
        return {"score": 0, "detail": "The target roster-release task is missing."}
    passed = row["status"] == "complete" and row["evidence_status"] == "verified"
    return {
        "score": 1 if passed else 0,
        "detail": (
            "IMP-24-088 remains complete and its evidence is verified."
            if passed
            else f"Observed status={row['status']!r}, evidence_status={row['evidence_status']!r}."
        ),
    }


def check_single_traceable_evidence_update(ws):
    current = _connect(_db_path(ws))
    try:
        total = current.execute("SELECT COUNT(*) FROM task_updates").fetchone()[0]
        matching_rows = current.execute(
            "SELECT * FROM task_updates WHERE task_id = ? AND milestone_id = ? "
            "AND update_type = ? AND reported_status = ?",
            (TARGET_TASK_ID, "MS-BCHS-IMPLEMENT", "completion_evidence", "complete"),
        ).fetchall()
    finally:
        current.close()
    matching_rows = [
        row
        for row in matching_rows
        if _norm_label(row["evidence_reference"]) == _norm_label(EXPECTED_EVIDENCE)
        and _norm_label(EXPECTED_EVIDENCE) in _norm_label(row["update_note"])
    ]
    if total != BASELINE_UPDATE_COUNT + 1 or len(matching_rows) != 1:
        return {
            "score": 0,
            "detail": (
                "Expected one appended, traceable target update; "
                f"observed total updates={total} and matching updates={len(matching_rows)}."
            ),
        }
    return {
        "score": 1,
        "detail": "Exactly one traceable completion-evidence update cites the approved October rota extract.",
    }


def check_target_business_fields_preserved(ws):
    current = _connect(_db_path(ws))
    baseline = _connect(_baseline_path(ws))
    try:
        current_row = _row_dict(
            current.execute(
                "SELECT * FROM implementation_tasks WHERE task_id = ?",
                (TARGET_TASK_ID,),
            ).fetchone()
        )
        baseline_row = _row_dict(
            baseline.execute(
                "SELECT * FROM implementation_tasks WHERE task_id = ?",
                (TARGET_TASK_ID,),
            ).fetchone()
        )
    finally:
        current.close()
        baseline.close()
    if current_row is None or baseline_row is None:
        return {"score": 0, "detail": "The target task is missing from current or baseline data."}
    changed = [
        column
        for column in baseline_row
        if column != "evidence_status" and current_row.get(column) != baseline_row[column]
    ]
    return {
        "score": 0 if changed else 1,
        "detail": (
            "All target-task fields other than evidence status were preserved."
            if not changed
            else "Unexpected target-task changes: " + ", ".join(changed) + "."
        ),
    }


def check_unrelated_tasks_and_history_preserved(ws):
    current = _connect(_db_path(ws))
    try:
        unrelated_tasks = [
            dict(row)
            for row in current.execute(
                "SELECT * FROM implementation_tasks WHERE task_id <> ? ORDER BY task_id",
                (TARGET_TASK_ID,),
            ).fetchall()
        ]
        updates = [
            dict(row)
            for row in current.execute(
                "SELECT * FROM task_updates ORDER BY task_update_id"
            ).fetchall()
        ]
    finally:
        current.close()
    if len(unrelated_tasks) != BASELINE_TASK_COUNT - 1 or _logical_digest(unrelated_tasks) != UNRELATED_TASKS_DIGEST:
        return {"score": 0, "detail": "One or more unrelated implementation tasks changed."}
    if len(updates) == BASELINE_UPDATE_COUNT and _logical_digest(updates) == BASELINE_UPDATES_DIGEST:
        return {
            "score": 1,
            "detail": "Unrelated tasks and all pre-existing update history were preserved.",
        }
    removable = []
    if len(updates) == BASELINE_UPDATE_COUNT + 1:
        for index, row in enumerate(updates):
            if _logical_digest(updates[:index] + updates[index + 1 :]) == BASELINE_UPDATES_DIGEST:
                removable.append(row)
    if len(removable) != 1 or removable[0]["task_id"] != TARGET_TASK_ID:
        return {
            "score": 0,
            "detail": "Existing history changed, or history was appended outside the target task.",
        }
    return {
        "score": 1,
        "detail": "Unrelated tasks and all pre-existing update history were preserved.",
    }
